import React, { useState, useEffect } from 'react';
import { supabase } from '../../services/supabase';
import Card from './Card';
import Button from './Button';

const DatabaseStatus = () => {
  const [status, setStatus] = useState('checking');
  const [error, setError] = useState(null);

  useEffect(() => {
    checkDatabaseStatus();
  }, []);

  const checkDatabaseStatus = async () => {
    try {
      // Test if we can access the users table
      const { error } = await supabase
        .from('users')
        .select('count')
        .limit(1);

      if (error) {
        if (error.code === '42P01') {
          setStatus('setup_required');
          setError('Database tables not found');
        } else {
          setStatus('error');
          setError(error.message);
        }
      } else {
        setStatus('ready');
      }
    } catch (err) {
      setStatus('error');
      setError(err.message);
    }
  };

  if (status === 'checking') {
    return (
      <div className="bg-white/80 backdrop-blur-sm border border-info-200/50 rounded-2xl p-6 mb-8 shadow-lg">
        <div className="flex items-center space-x-4">
          <div className="w-8 h-8 bg-gradient-to-br from-info-500 to-info-600 rounded-xl flex items-center justify-center">
            <div className="animate-spin rounded-full h-4 w-4 border-2 border-white border-t-transparent"></div>
          </div>
          <span className="text-info-800 font-semibold">Checking database status...</span>
        </div>
      </div>
    );
  }

  if (status === 'ready') {
    return null; // Don't show anything if database is ready
  }



  if (status === 'setup_required') {
    return (
      <Card className="p-6 mb-6 bg-yellow-50 border-yellow-200">
        <div className="flex items-start space-x-3">
          <svg className="w-6 h-6 text-yellow-600 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.964-.833-2.732 0L3.732 16.5c-.77.833.192 2.5 1.732 2.5z" />
          </svg>
          <div className="flex-1">
            <h3 className="text-lg font-semibold text-yellow-800 mb-2">
              Database Setup Required
            </h3>
            <p className="text-yellow-700 mb-4">
              Your database tables haven't been created yet. Please follow these steps to set up your database:
            </p>
            <div className="bg-yellow-100 p-4 rounded-lg mb-4">
              <ol className="list-decimal list-inside space-y-2 text-sm text-yellow-800">
                <li>Go to your <a href="https://supabase.com/dashboard" target="_blank" rel="noopener noreferrer" className="underline font-medium">Supabase Dashboard</a></li>
                <li>Select your project and open the <strong>SQL Editor</strong></li>
                <li>Copy the contents of <code className="bg-yellow-200 px-1 rounded">database/complete-schema.sql</code></li>
                <li>Paste and run the SQL to create all tables</li>
                <li>Refresh this page</li>
              </ol>
            </div>
            <div className="flex space-x-3">
              <Button
                onClick={checkDatabaseStatus}
                size="sm"
              >
                Check Again
              </Button>
              <Button
                onClick={() => window.open('https://supabase.com/dashboard', '_blank')}
                variant="outline"
                size="sm"
              >
                Open Supabase Dashboard
              </Button>
            </div>
          </div>
        </div>
      </Card>
    );
  }

  return (
    <Card className="p-6 mb-6 bg-red-50 border-red-200">
      <div className="flex items-start space-x-3">
        <svg className="w-6 h-6 text-red-600 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
        </svg>
        <div className="flex-1">
          <h3 className="text-lg font-semibold text-red-800 mb-2">
            Database Connection Error
          </h3>
          <p className="text-red-700 mb-4">
            There was an error connecting to your database: <code className="bg-red-100 px-1 rounded">{error}</code>
          </p>
          <div className="flex space-x-3">
            <Button
              onClick={checkDatabaseStatus}
              size="sm"
            >
              Retry Connection
            </Button>
            <Button
              onClick={() => window.open('https://supabase.com/dashboard', '_blank')}
              variant="outline"
              size="sm"
            >
              Check Supabase Dashboard
            </Button>
          </div>
        </div>
      </div>
    </Card>
  );
};

export default DatabaseStatus;
